import { useEffect, useState } from 'react';
import { getStudents } from '../../api';
import { Badge, Card, SectionTitle, Spinner } from '../../components/UI';

export default function AdminStudents() {
  const [students, setStudents] = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [search,   setSearch]   = useState('');

  useEffect(() => {
    getStudents().then(r => setStudents(r.data)).finally(() => setLoading(false));
  }, []);

  const filtered = students.filter(s =>
    s.full_name.toLowerCase().includes(search.toLowerCase()) ||
    s.email.toLowerCase().includes(search.toLowerCase())
  );

  if (loading) return <Spinner />;

  return (
    <div className="p-6 max-w-4xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-xl font-medium text-gray-900">Students</h1>
          <p className="text-sm text-gray-400 mt-0.5">{students.length} registered</p>
        </div>
        <input
          type="text"
          placeholder="Search name or email…"
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="border border-gray-200 rounded-xl px-3 py-2 text-sm w-56 focus:outline-none focus:ring-2 focus:ring-brand-200"
        />
      </div>
      <Card>
        <SectionTitle>All students</SectionTitle>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-xs text-gray-400 border-b border-gray-100">
                <th className="text-left pb-2 font-medium">ID</th>
                <th className="text-left pb-2 font-medium">Name</th>
                <th className="text-left pb-2 font-medium">Email</th>
                <th className="text-left pb-2 font-medium">Gender</th>
                <th className="text-left pb-2 font-medium">Enrolled</th>
                <th className="text-left pb-2 font-medium">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filtered.map(s => (
                <tr key={s.student_id}>
                  <td className="py-2.5 font-mono text-xs text-gray-400">S{String(s.student_id).padStart(3,'0')}</td>
                  <td className="py-2.5 font-medium text-gray-800">{s.full_name}</td>
                  <td className="py-2.5 text-gray-500 text-xs">{s.email}</td>
                  <td className="py-2.5 text-gray-400 text-xs">{s.gender || '—'}</td>
                  <td className="py-2.5 text-gray-400 text-xs">
                    {s.enrollment_date ? new Date(s.enrollment_date).toLocaleDateString() : '—'}
                  </td>
                  <td className="py-2.5">
                    <Badge label={s.is_active ? 'Active' : 'Inactive'} variant={s.is_active ? 'green' : 'gray'} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}
